//! Edge-case integration tests for scale-stat (round 2) — generated by bug-hunter agent.
//!
//! Focus: numeric precision in scale/tick math, boundary values in scene nodes,
//! degenerate inputs, and structural round-trip correctness.

use ferrum_scene::{
    BlendMode, Color, CoordKind, FillStroke, FontWeight, LayoutScale, MarkBatch, MarkBatchKind,
    Panel, PathCmd, Rect, SceneGraph, SceneNode, TextAnchor, TextBaseline,
    TextStyle, Tick, TickLevel,
};

fn default_text_style() -> TextStyle {
    TextStyle {
        font_size: 12.0,
        font_weight: FontWeight::Normal,
        anchor: TextAnchor::Start,
        baseline: TextBaseline::Alphabetic,
        angle: 0.0,
        color: Color::rgb(0, 0, 0),
        opacity: 1.0,
        font_family: "sans-serif".to_string(),
    }
}

fn default_fill_stroke() -> FillStroke {
    FillStroke {
        fill: Some(Color::rgb(70, 130, 180)),
        stroke: None,
        stroke_width: 0.0,
        opacity: 1.0,
        stroke_dash: None,
        stroke_opacity: 1.0,
        fill_opacity: 1.0,
        angle: 0.0,
    }
}

fn make_panel(marks: Vec<MarkBatch>) -> Panel {
    Panel {
        id: 0,
        plot_area: Rect { x: 50.0, y: 10.0, w: 500.0, h: 350.0 },
        clip: Rect { x: 50.0, y: 10.0, w: 500.0, h: 350.0 },
        coord: CoordKind::Cartesian {
            x_domain: Some((0.0, 10.0)),
            y_domain: Some((0.0, 10.0)),
            expand: true,
            clip: true,
        },
        grid: vec![],
        marks,
        axes: vec![],
        annotations: vec![],
        strip_title: vec![],
        layout_scale: LayoutScale::identity(),
    }
}

// ── FillStroke edge cases (round 2) ─────────────────────────────────────

#[test]
fn fill_stroke_angle_360_round_trips() {
    let fs = FillStroke {
        angle: 360.0,
        ..default_fill_stroke()
    };
    let json = serde_json::to_string(&fs).expect("serialize angle=360");
    let back: FillStroke = serde_json::from_str(&json).expect("deserialize");
    assert_eq!(back.angle, 360.0);
}

#[test]
fn fill_stroke_nan_angle_serializes_as_null() {
    let fs = FillStroke {
        angle: f64::NAN,
        ..default_fill_stroke()
    };
    let json = serde_json::to_string(&fs).expect("serialize NaN angle");
    assert!(!json.contains("NaN"), "NaN angle must serialize as null: {json}");
}

#[test]
fn fill_stroke_over_one_opacity_round_trips() {
    let fs = FillStroke {
        opacity: 2.5,
        stroke_opacity: 1.5,
        fill_opacity: 3.0,
        ..default_fill_stroke()
    };
    let json = serde_json::to_string(&fs).expect("serialize over-one opacity");
    let back: FillStroke = serde_json::from_str(&json).expect("deserialize");
    assert_eq!(back.opacity, 2.5);
}

#[test]
fn fill_stroke_negative_opacity_round_trips() {
    let fs = FillStroke {
        opacity: -0.5,
        stroke_opacity: -1.0,
        fill_opacity: -2.0,
        ..default_fill_stroke()
    };
    let json = serde_json::to_string(&fs).expect("serialize negative opacity");
    let back: FillStroke = serde_json::from_str(&json).expect("deserialize");
    assert_eq!(back.opacity, -0.5);
}

#[test]
fn fill_stroke_negative_stroke_width_round_trips() {
    let fs = FillStroke {
        stroke: Some(Color::rgb(255, 0, 0)),
        stroke_width: -2.0,
        ..default_fill_stroke()
    };
    let json = serde_json::to_string(&fs).expect("serialize negative stroke_width");
    let back: FillStroke = serde_json::from_str(&json).expect("deserialize");
    assert_eq!(back.stroke_width, -2.0);
}

